(() => {
  const { findByName, findByStoreName } = vendetta.metro;
  const { after } = vendetta.patcher;
  const { React, ReactNative } = vendetta.metro.common;
  const { useProxy } = vendetta.storage;
  const { FormSection, FormRow, FormSwitch, FormDivider } = vendetta.ui.components.Forms;
  const storage = vendetta.plugin.storage;
  const h = React.createElement;

  // Rasmlar plagin ichida (base64 PNG), internetga bog'liq emas.
  const IMG = {"account-age_blossom":"","account-age_bristlecone":"","account-age_bud":"","account-age_primordial":"","account-age_redwood":"","account-age_sapling":"","account-age_seed":"","account-age_sequoia":"","account-age_sprout":"","account-age_stromatolite":"","game-time_casual":"","game-time_committed":"","game-time_dedicated":"","game-time_devoted":"","game-time_eternal":"","game-time_ironclad":"","game-time_recreational":"","game-time_seasoned":"","game-time_serious":"","game-time_unshakeable":"","game-variety_adventurer":"","game-variety_dabbler":"","game-variety_enthusiast":"","game-variety_explorer":"","game-variety_maverick":"","game-variety_polymath":"","game-variety_ranger":"","game-variety_sampler":"","game-variety_universalist":"","game-variety_voyager":"","gifting_champion":"","gifting_hero":"","gifting_icon":"","gifting_legend":"","gifting_luminary":"","gifting_patron":"","nitro_bronze":"","nitro_diamond":"","nitro_emerald":"","nitro_gold":"","nitro_opal":"","nitro_platinum":"","nitro_ruby":"","nitro_silver":"","profile_active-developer":"","profile_app-premium":"","profile_bug-hunter-level-1":"","profile_bug-hunter-level-2":"","profile_completed-a-quest":"","profile_discord-nitro":"","profile_discord-staff":"","profile_early-supporter":"","profile_early-verified-bot-developer":"","profile_hypesquad-balance":"","profile_hypesquad-bravery":"","profile_hypesquad-brilliance":"","profile_hypesquad-events":"","profile_legacy-username":"","profile_moderator-programs-alumni":"","profile_orbs-apprentice":"","profile_partnered-server-owner":"","profile_supports-commands":"","profile_uses-automod":"","server-boost_server-boost-1":"","server-boost_server-boost-2":"","server-boost_server-boost-3":"","server-boost_server-boost-4":"","server-boost_server-boost-5":"","server-boost_server-boost-6":"","server-boost_server-boost-7":"","server-boost_server-boost-8":"","server-boost_server-boost-9":"","streaming_breakout":"","streaming_fledgling":"","streaming_headliner":"","streaming_newcomer":"","streaming_phenomenon":"","streaming_sensation":"","streaming_standout":"","streaming_star":"","streaming_trendsetter":"","streaming_visionary":""};
  const uri = (k) => "data:image/png;base64," + IMG[k];

  // Bitta badge'lar (yoq/o'chir)
  const SINGLES = [
    ["profile_discord-staff", "Discord Staff"],
    ["profile_partnered-server-owner", "Partnered Server Owner"],
    ["profile_hypesquad-events", "HypeSquad Events"],
    ["profile_hypesquad-bravery", "HypeSquad Bravery"],
    ["profile_hypesquad-brilliance", "HypeSquad Brilliance"],
    ["profile_hypesquad-balance", "HypeSquad Balance"],
    ["profile_bug-hunter-level-1", "Bug Hunter Level 1"],
    ["profile_bug-hunter-level-2", "Bug Hunter Level 2"],
    ["profile_early-supporter", "Early Supporter"],
    ["profile_early-verified-bot-developer", "Early Verified Bot Developer"],
    ["profile_moderator-programs-alumni", "Moderator Programs Alumni"],
    ["profile_active-developer", "Active Developer"],
    ["profile_discord-nitro", "Discord Nitro"],
    ["profile_supports-commands", "Supports Commands"],
    ["profile_uses-automod", "Uses AutoMod"],
    ["profile_completed-a-quest", "Completed a Quest"],
    ["profile_legacy-username", "Originally known as"],
    ["profile_orbs-apprentice", "Orbs Apprentice"],
    ["profile_app-premium", "App Premium"],
  ];

  // Darajali badge'lar: har birida bitta daraja tanlanadi (0 = o'chiq)
  const mk = (prefix, names, subs) =>
    names.map((n, i) => ({ key: prefix + n.toLowerCase().replace(/ /g, "-"), name: n, sub: subs[i] }));
  const CATS = [
    { key: "nitro", title: "Nitro obunasi",
      items: mk("nitro_", ["Bronze", "Silver", "Gold", "Platinum", "Diamond", "Emerald", "Ruby", "Opal"],
        ["1 oy", "3 oy", "6 oy", "1 yil", "2 yil", "3 yil", "5 yil", "6+ yil"]) },
    { key: "boost", title: "Server Boost",
      items: [1, 2, 3, 4, 5, 6, 7, 8, 9].map((n, i) => ({
        key: "server-boost_server-boost-" + n, name: "Boost " + n,
        sub: ["1 oy", "2 oy", "3 oy", "6 oy", "9 oy", "1 yil", "1 yil 3 oy", "1 yil 6 oy", "2+ yil"][i] })) },
    { key: "age", title: "Akkaunt yoshi",
      items: mk("account-age_", ["Seed", "Sprout", "Bud", "Sapling", "Blossom", "Redwood", "Sequoia", "Bristlecone", "Stromatolite", "Primordial"],
        ["1 yil", "2 yil", "3 yil", "4 yil", "5 yil", "6 yil", "7 yil", "8 yil", "9 yil", "10+ yil"]) },
    { key: "stream", title: "Stream (efir)",
      items: mk("streaming_", ["Newcomer", "Fledgling", "Breakout", "Standout", "Trendsetter", "Headliner", "Star", "Sensation", "Visionary", "Phenomenon"],
        ["1 soat", "5 soat", "20 soat", "75 soat", "150 soat", "300 soat", "500 soat", "1000 soat", "2000 soat", "5000+ soat"]) },
    { key: "time", title: "O'yin vaqti",
      items: mk("game-time_", ["Casual", "Recreational", "Dedicated", "Committed", "Serious", "Devoted", "Seasoned", "Ironclad", "Unshakeable", "Eternal"],
        ["1 soat", "5 soat", "20 soat", "75 soat", "150 soat", "300 soat", "500 soat", "1000 soat", "2000 soat", "5000+ soat"]) },
    { key: "variety", title: "O'yin xilma-xilligi",
      items: mk("game-variety_", ["Sampler", "Dabbler", "Enthusiast", "Ranger", "Explorer", "Adventurer", "Voyager", "Maverick", "Polymath", "Universalist"],
        ["2 o'yin", "5 o'yin", "10 o'yin", "15 o'yin", "20 o'yin", "30 o'yin", "40 o'yin", "60 o'yin", "80 o'yin", "100+ o'yin"]) },
    { key: "gift", title: "Sovg'alar",
      items: mk("gifting_", ["Patron", "Champion", "Luminary", "Icon", "Hero", "Legend"],
        ["1 sovg'a", "2 sovg'a", "3 sovg'a", "6 sovg'a", "10 sovg'a", "20 sovg'a"]) },
  ];

  const PREFIX = "localbadge-";
  const NAMES = ["RenderedBadge", "ProfileBadge", "UserProfileBadge"];
  const props = {};
  let unpatch, jsxCb;
  let hits = 0, injected = 0;

  const level = (c) => {
    const v = storage.levels?.[c.key];
    return typeof v === "number" ? Math.max(0, Math.min(c.items.length, v)) : c.items.length;
  };
  const singleOn = (k) => storage.singles?.[k] !== false;

  function activeBadges() {
    const out = [];
    SINGLES.forEach(([k, label]) => { if (singleOn(k)) out.push({ key: k, label }); });
    CATS.forEach((c) => {
      const lv = level(c);
      if (lv > 0) { const it = c.items[lv - 1]; out.push({ key: it.key, label: c.title + ": " + it.name + " (" + it.sub + ")" }); }
    });
    return out.filter((b) => IMG[b.key]);
  }

  function Settings() {
    useProxy(storage);
    const { ScrollView, Image } = ReactNative;
    const icon = (k) => h(Image, { source: { uri: uri(k) }, style: { width: 28, height: 28 } });
    const setAll = (on) => {
      storage.singles = {}; SINGLES.forEach(([k]) => { storage.singles[k] = on; });
      storage.levels = {}; CATS.forEach((c) => { storage.levels[c.key] = on ? c.items.length : 0; });
    };

    const tiers = CATS.map((c) => {
      const lv = level(c), n = c.items.length, it = lv > 0 ? c.items[lv - 1] : null;
      return h(FormRow, {
        key: c.key, label: c.title,
        subLabel: it ? it.name + " (" + it.sub + ")  -  " + lv + "/" + n + "  (bosib keyingisiga)" : "O'chiq  (bosib yoqing)",
        leading: it ? icon(it.key) : undefined,
        onPress: () => { storage.levels = { ...(storage.levels || {}), [c.key]: (lv + 1) % (n + 1) }; },
      });
    });
    const singles = SINGLES.map(([k, label]) =>
      h(FormRow, {
        key: k, label, leading: icon(k),
        trailing: h(FormSwitch, { value: singleOn(k), onValueChange: (v) => { storage.singles = { ...(storage.singles || {}), [k]: v }; } }),
      }));

    return h(ScrollView, { style: { flex: 1 } },
      h(FormSection, { title: "Holat", key: "s0" },
        h(FormRow, { label: "Ro'yxatga qo'shilgan badge'lar", subLabel: String(injected) + " marta (profilni ochganda oshadi)" }),
        h(FormRow, { label: "Rasm almashtirish ishladi", subLabel: String(hits) + " marta (0 bo'lib qolsa, menga ayting)" }),
        h(FormRow, { label: "Hammasini yoqish", onPress: () => setAll(true) }),
        h(FormRow, { label: "Hammasini o'chirish", onPress: () => setAll(false) })),
      h(FormSection, { title: "Darajalar (bosib o'zgartiring)", key: "s1" }, ...tiers),
      h(FormSection, { title: "Alohida badge'lar", key: "s2" }, ...singles),
      h(FormSection, { title: "Eslatma", key: "s3" },
        h(FormRow, { label: "Hammasi faqat sizga ko'rinadi", subLabel: "Boshqa foydalanuvchilar bu badge'larni ko'rmaydi. O'zgartirgach profilni qayta oching." })));
  }

  return {
    onLoad() {
      storage.singles ??= {};
      storage.levels ??= {};
      const UserStore = findByStoreName("UserStore");
      const useBadges = findByName("useBadges", false);
      const jsx = globalThis.bunny.api.react.jsx;

      jsxCb = (_, ret) => {
        const id = ret?.props?.id;
        if (typeof id === "string" && props[id]) { Object.assign(ret.props, props[id]); hits++; }
      };
      NAMES.forEach((n) => jsx.onJsxCreate(n, jsxCb));

      unpatch = after("default", useBadges, ([user], r) => {
        if (!user || !Array.isArray(r)) return;
        const me = UserStore.getCurrentUser?.()?.id;
        if (!me || user.userId !== me) return; // faqat o'zingizda
        activeBadges().forEach((b) => {
          const id = PREFIX + b.key;
          if (r.some((x) => x && x.id === id)) return;
          const source = { uri: uri(b.key) };
          props[id] = { source, id, label: b.label };
          r.push({ id, description: b.label, icon: "_", source });
          injected++;
        });
      });
    },

    onUnload() {
      unpatch?.();
      const jsx = globalThis.bunny?.api?.react?.jsx;
      if (jsx && jsxCb) NAMES.forEach((n) => jsx.deleteJsxCreate(n, jsxCb));
    },

    settings: Settings,
  };
})()
